import { z } from 'zod';
import { modelSrcInputSchema, modelInputToSrcSchema, MODEL_SOURCE_URI_HINT } from './model-src-utils.js';
const ASSET_SRC_DESCRIPTION = `The asset to download and cache: ${MODEL_SOURCE_URI_HINT}.`;
const downloadAssetOptionsBaseSchema = z.object({
    assetSrc: modelSrcInputSchema.describe(ASSET_SRC_DESCRIPTION),
    seed: z.boolean().optional(),
    requireHttpChecksum: z.boolean().optional(),
    requireSecureTransport: z.boolean().optional()
});
export const downloadAssetOptionsSchema = downloadAssetOptionsBaseSchema.transform((data) => ({
    ...data,
    seed: data.seed ?? false
}));
export const downloadAssetOptionsToRequestSchema = downloadAssetOptionsBaseSchema
    .extend({
    onProgress: z.unknown().optional(),
    withProgress: z.boolean().optional(),
    requestId: z.string().min(1).optional()
})
    .transform((data) => {
    const out = {
        type: 'downloadAsset',
        assetSrc: modelInputToSrcSchema.parse(data.assetSrc),
        withProgress: data.withProgress ?? !!data.onProgress,
        seed: data.seed ?? false
    };
    if (data.requestId !== undefined)
        out.requestId = data.requestId;
    if (data.requireHttpChecksum !== undefined)
        out.requireHttpChecksum = data.requireHttpChecksum;
    if (data.requireSecureTransport !== undefined) {
        out.requireSecureTransport = data.requireSecureTransport;
    }
    return out;
});
export const downloadAssetRequestSchema = z
    .object({
    type: z.literal('downloadAsset'),
    assetSrc: z.string().describe(ASSET_SRC_DESCRIPTION),
    withProgress: z.boolean().optional(),
    seed: z.boolean().optional(),
    requireHttpChecksum: z
        .boolean()
        .optional()
        .describe('Reject a Hugging Face HTTP download that exposes no usable SHA-256 instead of downloading it unverified. Overrides the engine config for this call; defaults to the config value (false).'),
    requireSecureTransport: z
        .boolean()
        .optional()
        .describe('Reject plaintext http:// and HTTPS→HTTP downgrades for every HTTP source on this call (loopback exempt); when unset, only Hugging Face transport is hardened. Overrides the engine config for this call; defaults to the config value (false).'),
    requestId: z
        .string()
        .min(1)
        .optional()
        .describe('Stable identifier for this in-flight download, generated by the caller at call time. Optional — falls back to a generated id when the field is missing. Exposed on the decorated promise so callers can target this download with `cancel({ requestId })`.')
})
    .transform((data) => ({
    ...data,
    seed: data.seed ?? false
}));
export const downloadAssetResponseSchema = z.object({
    type: z.literal('downloadAsset'),
    success: z.boolean(),
    assetId: z.string().optional(),
    error: z.string().optional()
});
const downloadTypes = ['hyperdrive', 'http', 'registry'];
export const downloadTypeSchema = z.enum(downloadTypes);
export const sourceTypeSchema = z.enum([...downloadTypes, 'filesystem']);
export const downloadMetadataSchema = z.object({
    key: z.string(),
    startTime: z.number(),
    type: downloadTypeSchema
});
export const hyperdriveDownloadMetadataSchema = downloadMetadataSchema.extend({
    type: z.literal('hyperdrive'),
    hyperdriveKey: z.string(),
    modelFileName: z.string()
});
export const httpDownloadMetadataSchema = downloadMetadataSchema.extend({
    type: z.literal('http'),
    url: z.url(),
    modelPath: z.string()
});
export const registryDownloadMetadataSchema = downloadMetadataSchema.extend({
    type: z.literal('registry'),
    registryPath: z.string()
});
